import * as THREE from 'three/webgpu';
import { texture, uv, vec2, mix, float, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;

  const width = 1.4;
  const height = width / aspect;

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  // Atlas region 0,0,512,320 out of an assumed 512x320 (full) atlas texture
  // Compute normalized UV offset/repeat
  const atlasW = 512;
  const atlasH = 320;
  const uOffset = atlasRect.x / atlasW;
  const vOffset = 1.0 - (atlasRect.y + atlasRect.h) / atlasH;
  const uRepeat = atlasRect.w / atlasW;
  const vRepeat = atlasRect.h / atlasH;

  const remappedUV = uv().mul(vec2(uRepeat, vRepeat)).add(vec2(uOffset, vOffset));

  const baseColor = texture(map, remappedUV);

  // Engineered gradient overlay: subtle ink -> surface gradient tinted by paper, no soft blur
  const inkColor = color(new THREE.Color(config?.visual?.colors?.ink ?? '#16161d'));
  const surfaceColor = color(new THREE.Color(config?.visual?.colors?.surface ?? '#0b0b10'));
  const gradientFactor = uv().y;
  const engineeredGradient = mix(surfaceColor, inkColor, gradientFactor);

  const finalColor = mix(baseColor, engineeredGradient, float(0.12));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = finalColor;
  material.transparent = false;
  material.toneMapped = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-journal-card-1-image';

  const node = new THREE.Object3D();
  node.name = 'hub-journal-card-1';
  node.add(mesh);

  node.position.set(0, -0.3, 0);
  node.rotation.set(0, 0, 0);
  node.scale.set(1, 1, 1);

  // Billboard toward camera on each frame via onBeforeRender
  node.onBeforeRender = (renderer, scene, camera) => {
    node.quaternion.copy(camera.quaternion);
  };

  node.userData.handlers = {};

  node.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    node.onBeforeRender = null;
  };

  return node;
}
